const msg = $input.first().json.message || {};
const chatId = String(msg.chat && msg.chat.id);
const text = (msg.text || '').trim();
return [{
  json: {
    telegram_user: chatId,
    text,
    nombre: (msg.from && (msg.from.first_name || '')) || ''
  }
}];

const items = $input.all();
const norm = $('Normalizar entrada').item.json;
let pantalla_actual = 'INICIO';
let datos_parciales_raw = '{}';
if (items.length > 0) {
  const s = items[0].json;
  pantalla_actual = s.pantalla_actual || 'INICIO';
  datos_parciales_raw = s.datos_parciales || '{}';
}
if (norm.text === '/start') {
  pantalla_actual = 'INICIO';
  datos_parciales_raw = '{}';
}
let datos = {};
try { datos = JSON.parse(datos_parciales_raw); } catch (e) { datos = {}; }
return [{
  json: {
    telegram_user: norm.telegram_user,
    text: norm.text,
    nombre: norm.nombre,
    pantalla_actual,
    datos_parciales_raw,
    datos
  }
}];

const text = ($json.text || '').trim().toLowerCase();
const telegram_user = $json.telegram_user;
let accion = 'bienvenida';
if (text === '1' || text.includes('registrar')) accion = 'registro';
else if (text === '2' || text.includes('estudiante')) accion = 'pedir_id';
return [{ json: { telegram_user, accion } }];

const items = $input.all();
const encontrado = items.length > 0;
const telegram_user = $('Preparar estado').item.json.telegram_user;
if (encontrado) {
  const est = items[0].json;
  return [{ json: {
    resultado: 'encontrado',
    telegram_user,
    id_estudiante: est.id_estudiante,
    nombre: est.nombre || '',
    mensaje: `Hola ${est.nombre || ''}! Que deseas hacer?\n1. Consultar mis tutorias\n2. Agendar tutoria\n3. Eliminar tutoria`,
    pantalla_actual: 'MENU_ESTUDIANTE',
    datos_parciales: JSON.stringify({ id_estudiante: est.id_estudiante })
  }}];
}
return [{ json: {
  resultado: 'no_encontrado',
  telegram_user,
  mensaje: 'No encontramos ese ID de estudiante. Registrate primero aqui: https://TU-INSTANCIA-N8N.app.n8n.cloud/form/registro-tutorbot\n\nTu codigo de Telegram es: ' + telegram_user + '\n\nCuando termines, escribeme /start.',
  pantalla_actual: 'INICIO',
  datos_parciales: '{}'
}}];

const text = ($json.text || '').trim().toLowerCase();
const telegram_user = $json.telegram_user;
const id_estudiante = ($json.datos && $json.datos.id_estudiante) || '';
let opcion = 'invalido';
if (text === '1' || text.includes('consultar')) opcion = 'consultar';
else if (text === '2' || text.includes('agendar')) opcion = 'agendar';
else if (text === '3' || text.includes('eliminar')) opcion = 'eliminar';
return [{ json: { telegram_user, id_estudiante, opcion } }];

const items = $input.all();
const id_estudiante = $('Procesar opcion menu').item.json.id_estudiante;
const telegram_user = $('Procesar opcion menu').item.json.telegram_user;
let mensaje;
if (!items.length) {
  mensaje = 'No tienes tutorias registradas todavia.';
} else {
  const lineas = items.map(i => {
    const t = i.json;
    return `#${t.id_tutoria} - ${t.materia} - ${t.fecha} ${t.hora} - Estado: ${t.estado}`;
  });
  mensaje = 'Tus tutorias:\n' + lineas.join('\n');
}
mensaje += '\n\nQue deseas hacer?\n1. Consultar mis tutorias\n2. Agendar tutoria\n3. Eliminar tutoria';
return [{ json: {
  telegram_user, id_estudiante, mensaje,
  pantalla_actual: 'MENU_ESTUDIANTE',
  datos_parciales: JSON.stringify({ id_estudiante })
}}];

const tutoresRaw = $('Leer tutores activos').all().map(i => i.json);
const dispoRaw = $input.all().map(i => i.json);
const dispoMap = new Map();
for (const d of dispoRaw) dispoMap.set(d.id_dispo, d);
const dispo = Array.from(dispoMap.values()).filter(d => String(d.estado).toLowerCase() === 'libre');
const tutorMap = new Map(tutoresRaw.map(t => [t.id_tutor, t]));
const opciones = [];
for (const d of dispo) {
  const t = tutorMap.get(d.id_tutor);
  if (!t) continue;
  opciones.push({
    id_dispo: d.id_dispo, id_tutor: d.id_tutor, tutor_nombre: t.nombre,
    materias: t.especialidad_materias, dia_semana: d.dia_semana,
    hora_inicio: d.hora_inicio, hora_fin: d.hora_fin
  });
}
const telegram_user = $('Procesar opcion menu').item.json.telegram_user;
const id_estudiante = $('Procesar opcion menu').item.json.id_estudiante;
let mensaje, pantalla_actual;
if (opciones.length === 0) {
  mensaje = 'No hay tutores disponibles en este momento. Intenta mas tarde.\n\nQue deseas hacer?\n1. Consultar mis tutorias\n2. Agendar tutoria\n3. Eliminar tutoria';
  pantalla_actual = 'MENU_ESTUDIANTE';
} else {
  mensaje = 'Elige una opcion escribiendo su numero:\n' + opciones.map((o, i) =>
    `${i + 1}. ${o.materias} - ${o.tutor_nombre} - ${o.dia_semana} ${o.hora_inicio}-${o.hora_fin}`).join('\n');
  pantalla_actual = 'ESPERANDO_SLOT';
}
return [{ json: {
  telegram_user, id_estudiante, mensaje, pantalla_actual,
  datos_parciales: JSON.stringify({ id_estudiante, opciones })
}}];

const items = $input.all().map(i => i.json).filter(t => ['Asignada', 'Confirmada'].includes(t.estado));
const telegram_user = $('Procesar opcion menu').item.json.telegram_user;
const id_estudiante = $('Procesar opcion menu').item.json.id_estudiante;
let mensaje, pantalla_actual;
if (!items.length) {
  mensaje = 'No tienes tutorias que se puedan eliminar.\n\nQue deseas hacer?\n1. Consultar mis tutorias\n2. Agendar tutoria\n3. Eliminar tutoria';
  pantalla_actual = 'MENU_ESTUDIANTE';
} else {
  mensaje = 'Elige cual deseas eliminar escribiendo su numero:\n' + items.map((t, i) =>
    `${i + 1}. ${t.materia} - ${t.fecha} ${t.hora} - Estado: ${t.estado}`).join('\n');
  pantalla_actual = 'ESPERANDO_ELIMINAR';
}
return [{ json: {
  telegram_user, id_estudiante, mensaje, pantalla_actual,
  datos_parciales: JSON.stringify({ id_estudiante, opciones: items })
}}];

const text = ($json.text || '').trim();
const idx = parseInt(text, 10);
const opciones = ($json.datos && $json.datos.opciones) || [];
const telegram_user = $json.telegram_user;
const id_estudiante = ($json.datos && $json.datos.id_estudiante) || '';
let mensaje, pantalla_actual, datos_parciales;
if (!isNaN(idx) && idx >= 1 && idx <= opciones.length) {
  const elegido = opciones[idx - 1];
  mensaje = `Elegiste: ${elegido.materias} con ${elegido.tutor_nombre} (${elegido.dia_semana} ${elegido.hora_inicio}-${elegido.hora_fin}).\nEscribe la fecha exacta (formato AAAA-MM-DD).`;
  pantalla_actual = 'ESPERANDO_FECHA';
  datos_parciales = JSON.stringify({ id_estudiante, opcion_elegida: elegido });
} else {
  mensaje = 'No reconozco esa opcion. Escribe el numero de la opcion que quieres elegir:\n' +
    opciones.map((o, i) => `${i + 1}. ${o.materias} - ${o.tutor_nombre} - ${o.dia_semana} ${o.hora_inicio}-${o.hora_fin}`).join('\n');
  pantalla_actual = 'ESPERANDO_SLOT';
  datos_parciales = JSON.stringify({ id_estudiante, opciones });
}
return [{ json: { telegram_user, id_estudiante, mensaje, pantalla_actual, datos_parciales } }];

const text = ($json.text || '').trim();
const valido = /^\d{4}-\d{2}-\d{2}$/.test(text);
const telegram_user = $json.telegram_user;
const id_estudiante = ($json.datos && $json.datos.id_estudiante) || '';
const elegido = ($json.datos && $json.datos.opcion_elegida) || {};
let out = { telegram_user, id_estudiante, valido };
if (valido) {
  out.id_tutoria = 'TUT-' + Date.now();
  out.id_tutor = elegido.id_tutor;
  out.id_dispo = elegido.id_dispo;
  out.materia = elegido.materias;
  out.fecha = text;
  out.hora = elegido.hora_inicio;
} else {
  out.mensaje = 'Formato de fecha invalido. Escribe la fecha como AAAA-MM-DD (ej: 2026-09-15).';
  out.datos_parciales = JSON.stringify({ id_estudiante, opcion_elegida: elegido });
}
return [{ json: out }];

const tutor = $input.first().json;
const v = $('Validar fecha').item.json;
const mensaje_estudiante = `Tu tutoria de ${v.materia} quedo agendada para el ${v.fecha} a las ${v.hora} con ${tutor.nombre || 'tu tutor'}.`;
const mensaje_tutor = `Nueva tutoria asignada: ${v.materia} el ${v.fecha} a las ${v.hora} (estudiante ${v.id_estudiante}).`;
return [{ json: {
  telegram_user: v.telegram_user, id_estudiante: v.id_estudiante,
  telegram_tutor: tutor.telegram_tutor, mensaje_estudiante, mensaje_tutor,
  pantalla_actual: 'MENU_ESTUDIANTE',
  datos_parciales: JSON.stringify({ id_estudiante: v.id_estudiante })
}}];

const text = ($json.text || '').trim();
const idx = parseInt(text, 10);
const opciones = ($json.datos && $json.datos.opciones) || [];
const telegram_user = $json.telegram_user;
const id_estudiante = ($json.datos && $json.datos.id_estudiante) || '';
let out = { telegram_user, id_estudiante };
if (!isNaN(idx) && idx >= 1 && idx <= opciones.length) {
  out.valido = true;
  out.elegida = opciones[idx - 1];
} else {
  out.valido = false;
  out.mensaje = 'No reconozco esa opcion. Escribe el numero de la tutoria que quieres eliminar:\n' +
    opciones.map((t, i) => `${i + 1}. ${t.materia} - ${t.fecha} ${t.hora} - Estado: ${t.estado}`).join('\n');
  out.datos_parciales = JSON.stringify({ id_estudiante, opciones });
}
return [{ json: out }];

const tutor = $input.first().json;
const e = $('Procesar seleccion eliminar').item.json;
const mensaje_estudiante = `Tu tutoria de ${e.elegida.materia} (${e.elegida.fecha} ${e.elegida.hora}) fue eliminada correctamente.`;
const mensaje_tutor = `La tutoria de ${e.elegida.materia} el ${e.elegida.fecha} a las ${e.elegida.hora} fue cancelada por el estudiante.`;
return [{ json: {
  telegram_user: e.telegram_user, id_estudiante: e.id_estudiante,
  telegram_tutor: tutor.telegram_tutor, mensaje_estudiante, mensaje_tutor,
  pantalla_actual: 'MENU_ESTUDIANTE',
  datos_parciales: JSON.stringify({ id_estudiante: e.id_estudiante })
}}];
